class TestResult {
  public boolean succeeded;
  public String reason;
  public String input;
  public String expected_output;
  public String actual_output;
}

class EdTestRunner {
  public static TestResult[] executeTests() throws IllegalArgumentException, IllegalAccessException {



    TestResult[] error = new TestResult[1];

    // 1: Checking if the required class exists or not
    try  {
      Class.forName("Student");
    }  catch (ClassNotFoundException e) {

      error[0] = new TestResult();
      error[0].reason = "Rectangle class is not found";
      error[0].succeeded = false;
      return error;
    }
    //


    // 2: Cheking if the requied fields exits or not

    Student obj = new Student();

    Field[] fields = obj.getClass().getDeclaredFields();

    if(fields.length != 2) {

      error[0] = new TestResult();
      error[0].reason = "Some Fields are missing";
      error[0].succeeded = false;
      return error;
    }

    for (Field field : fields) {
      if (Modifier.isPrivate(field.getModifiers())) {
        field.setAccessible(true);
        System.out.println("Private : " + field.getName());

        if(!((field.getName().equals("name")) || (field.getName().equals("rollNumber")))) {

          error[0] = new TestResult();
          error[0].reason = "Field names are not correct";
          error[0].succeeded = false;
          return error;

        }
      }
      else if (Modifier.isProtected(field.getModifiers())) {
        field.setAccessible(true);
        System.out.println("Protected : " + field.getName());

        error[0] = new TestResult();
        error[0].reason = "Fields shouldn't be protected";
        error[0].succeeded = false;
        return error;

      }

      else if (Modifier.isPublic(field.getModifiers())) {

        error[0] = new TestResult();
        error[0].reason = "Fields shouldn't be public";
        error[0].succeeded = false;

        field.setAccessible(true);
        System.out.println("Public : " + field.getName());
        return error;
      }
    }


    // Checking if the requird methods exists or not

    Method[] allMethods = Student.class.getDeclaredMethods();


    TestResult[] test_results = new TestResult[4];


    test_results[0] = new TestResult();
    test_results[0].input = "Checking Getter: getName";
    test_results[0].expected_output = String.valueOf("String getName()"); 
    test_results[0].reason = "Incorrect Output";
    test_results[0].succeeded = false;
    for (Method method : allMethods) {
      if (Modifier.isPublic(method.getModifiers())) {

        if(method.getName().equals("getName") && method.getReturnType().getName().equals("java.lang.String"))
        {
          test_results[0].actual_output = "String getName()";
          test_results[0].reason = "Succeeded";
          test_results[0].succeeded = true;
          break;
        }
      }
    }


    test_results[1] = new TestResult();
    test_results[1].input = "Checking Getter: getRollNumber";
    test_results[1].expected_output = String.valueOf("String getRollNumber()"); 
    test_results[1].reason = "Incorrect Output";
    test_results[1].succeeded = false;
    for (Method method : allMethods) {
      if (Modifier.isPublic(method.getModifiers())) {

        System.out.println(method.getParameters());

        if(method.getName().equals("getRollNumber") && method.getReturnType().getName().equals("java.lang.String"))
        {
          test_results[1].actual_output = "String getRollNumber()";
          test_results[1].reason = "Succeeded";
          test_results[1].succeeded = true;
          break;
        }
      }
    }


    test_results[2] = new TestResult();
    test_results[2].input = "Checking Setter: setRollNumber";
    test_results[2].expected_output = String.valueOf("void setRollNumber()"); 
    test_results[2].reason = "Incorrect Output";
    test_results[2].succeeded = false;
    for (Method method : allMethods) {
      if (Modifier.isPublic(method.getModifiers())) {

        if(method.getName().equals("setRollNumber") && method.getReturnType().getName().equals("void"))
        {
          test_results[2].actual_output = "void setRollNumber()";
          test_results[2].reason = "Succeeded";
          test_results[2].succeeded = true;
          break;
        }
      }
    }


    test_results[3] = new TestResult();
    test_results[3].input = "Checking Setter: setName";
    test_results[3].expected_output = String.valueOf("void setName()"); 
    test_results[3].reason = "Incorrect Output";
    test_results[3].succeeded = false;
    for (Method method : allMethods) {
      if (Modifier.isPublic(method.getModifiers())) {

        if(method.getName().equals("setName") && method.getReturnType().getName().equals("void"))
        {
          test_results[3].actual_output = "void setName()";
          test_results[3].reason = "Succeeded";
          test_results[3].succeeded = true;
          break;
        }
      }
    }

    return test_results;
  }
}

